import { APPROVE_LEGAL_CORRESPONDENCE } from "../auth/roles";
import { formatUkDateTime, nowUtcIso } from "../dates";
import { eventTypeForTemplate } from "../documents/catalog";
import { recordClaimEvent } from "./chronology";
import { all, get, run } from "./connection";
import { listStaffPermissions } from "./permissions";

/**
 * Case-specific legal arguments. A draft can be generated by anyone in the office. Marking one as sent, or emailing
 * it, needs Justin's approval first. Any letter-before-action or court template added later belongs in this list.
 */
export const LEGAL_APPROVAL_TEMPLATES: readonly string[] = ["rebuttal_rate", "rebuttal_need", "rebuttal_duration", "impecuniosity_disclosure"];

export const NEEDS_JUSTIN_APPROVAL = "Needs Justin's approval";

export function needsLegalApproval(templateKey: string | null | undefined): boolean {
  return LEGAL_APPROVAL_TEMPLATES.includes(String(templateKey || ""));
}

export function accountCanApproveLegal(staffId: string): boolean {
  return listStaffPermissions(staffId).includes(APPROVE_LEGAL_CORRESPONDENCE);
}

export type LegalApprovalState = {
  required: boolean;
  approvedBy: string | null;
  approvedAt: string | null;
  sentAt: string | null;
};

type DocRow = {
  id: string;
  claim_id: string;
  title: string;
  template_key: string | null;
  legal_approved_by: string | null;
  legal_approved_at: string | null;
  legal_sent_at: string | null;
  approver_name: string | null;
};

function readDoc(documentId: string): DocRow | undefined {
  return get<DocRow>(
    `SELECT d.id, d.claim_id, d.title, d.template_key, d.legal_approved_by, d.legal_approved_at, d.legal_sent_at, s.name AS approver_name
     FROM documents d LEFT JOIN staff s ON s.id = d.legal_approved_by WHERE d.id = ?`,
    [documentId],
  );
}

export function legalApprovalState(documentId: string): LegalApprovalState {
  const doc = readDoc(documentId);
  if (!doc || !needsLegalApproval(doc.template_key)) return { required: false, approvedBy: null, approvedAt: null, sentAt: null };
  return { required: true, approvedBy: doc.approver_name, approvedAt: doc.legal_approved_at, sentAt: doc.legal_sent_at };
}

export function approveLegalDocument(input: { documentId: string; actorId: string }) {
  const doc = readDoc(input.documentId);
  if (!doc || !needsLegalApproval(doc.template_key)) throw new Error("This document does not need approval.");
  if (!accountCanApproveLegal(input.actorId)) throw new Error(`${NEEDS_JUSTIN_APPROVAL}. Only Justin can approve this letter.`);
  if (doc.legal_approved_at) return;
  const at = nowUtcIso();
  run(`UPDATE documents SET legal_approved_by = ?, legal_approved_at = ? WHERE id = ?`, [input.actorId, at, doc.id]);
  const name = get<{ name: string }>(`SELECT name FROM staff WHERE id = ?`, [input.actorId])?.name || "Justin";
  recordClaimEvent({
    claimId: doc.claim_id,
    eventType: "legal_letter_approved",
    occurredAt: at,
    actorId: input.actorId,
    details: `${doc.title} approved for sending by ${name}.`,
    documentId: doc.id,
    source: "staff",
  });
}

/** Records the letter as sent, only once it is approved. The CRM does not post or email it. */
export function markLegalDocumentSent(input: { documentId: string; actorId: string }) {
  const doc = readDoc(input.documentId);
  if (!doc || !needsLegalApproval(doc.template_key)) throw new Error("This document is not one that needs approval.");
  if (!doc.legal_approved_at) throw new Error(`${NEEDS_JUSTIN_APPROVAL} before it is marked as sent.`);
  if (doc.legal_sent_at) throw new Error("This letter is already marked as sent.");
  const at = nowUtcIso();
  run(`UPDATE documents SET legal_sent_at = ? WHERE id = ?`, [at, doc.id]);
  const name = get<{ name: string }>(`SELECT name FROM staff WHERE id = ?`, [input.actorId])?.name || "staff";
  recordClaimEvent({
    claimId: doc.claim_id,
    eventType: eventTypeForTemplate(String(doc.template_key)),
    occurredAt: at,
    actorId: input.actorId,
    details: `${doc.title} marked as sent by ${name}. Approved by ${doc.approver_name || "Justin"} on ${formatUkDateTime(doc.legal_approved_at)}. Not sent from the CRM.`,
    documentId: doc.id,
    source: "staff",
  });
}

/** An email may not carry a legal letter that has not been approved. */
export function unapprovedLegalAttachment(claimId: string, documentIds: string[]): string | null {
  const ids = [...new Set(documentIds.map((id) => id.trim()).filter(Boolean))];
  if (ids.length === 0) return null;
  const marks = ids.map(() => "?").join(", ");
  const rows = all<{ title: string; template_key: string | null; legal_approved_at: string | null }>(
    `SELECT title, template_key, legal_approved_at FROM documents WHERE claim_id = ? AND id IN (${marks})`,
    [claimId, ...ids],
  );
  const blocked = rows.find((row) => needsLegalApproval(row.template_key) && !row.legal_approved_at);
  return blocked ? `${blocked.title}: ${NEEDS_JUSTIN_APPROVAL} before it is emailed. Nothing was sent.` : null;
}
